// Routes all three entry points with workflow static data (survives between executions when active).
const store = $getWorkflowStaticData('global');
store.alerts = store.alerts || {};
const s = $('Load Settings').first().json;
const now = Date.now();
const out = [];
const entry = $input.first().json;
const sevs = String(s.escalateSeverities).split(',').map(x => x.trim().toLowerCase());
if (entry.query && entry.query.ack) {               // ack link opened
  const a = store.alerts[entry.query.ack];
  if (a) { a.ackedAt = now; }
  return [{ json: { action: 'ack', id: entry.query.ack, found: !!a } }];
}
if (entry.body) {                                     // new alert
  const b = entry.body;
  const id = String(b.id || ('a-' + now));
  const sev = String(b.severity || 'info').toLowerCase();
  if (!sevs.includes(sev)) return [{ json: { action: 'ignore', id, severity: sev } }];
  if (!store.alerts[id]) store.alerts[id] = { id, title: String(b.title || 'Alert'), severity: sev, receivedAt: now, ackedAt: null, escalatedAt: null };
  out.push({ json: { action: 'notify', target: s.primaryUrl, id, title: store.alerts[id].title, ackUrl: s.baseUrl + '/webhook/escalation-ack?ack=' + encodeURIComponent(id) } });
  return out;
}
// scheduled check
const limit = Number(s.escalateAfterMinutes) * 60000;
for (const a of Object.values(store.alerts)) {
  if (!a.ackedAt && !a.escalatedAt && now - a.receivedAt >= limit) {
    a.escalatedAt = now;
    out.push({ json: { action: 'escalate', target: s.secondaryUrl, id: a.id, title: a.title, ackUrl: s.baseUrl + '/webhook/escalation-ack?ack=' + encodeURIComponent(a.id) } });
  }
  if (now - a.receivedAt > 7 * 86400000) delete store.alerts[a.id];   // keep store small
}
return out.length ? out : [{ json: { action: 'none' } }];
